import {createGame} from './game.mjs';
import {setupMap} from './map-interaction.mjs';
const $=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';
let photos=[],geometry=[],landmarks=[],game,sound=false,audio,ready=false,mapReady=false,mapView,activeLandmark=null;
function svg(tag,attrs,parent){const el=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);parent?.append(el);return el;}
function point(lat,lng){return mapView.camera.project(lat,lng);}
function drawMap(){if(mapView)mapView.render();}
function drawLandmarks(){
 const layer=$('landmarks');
 if(!layer.children.length)for(const p of landmarks){
  const g=svg('g',{class:'landmark','data-landmark':p.id,role:'button',tabindex:'0','aria-label':p.name,'aria-pressed':'false'},layer);
  const title=svg('title',{},g);title.textContent=p.name;
  svg('path',{d:'M0 -9V0',stroke:'#c8c9b3','stroke-width':1.5},g);
  svg('image',{href:p.image,x:-34,y:-74,width:68,height:68,'aria-hidden':'true',class:'landmark-image'},g);
  const label=svg('g',{class:'landmark-label','aria-hidden':'true'},g),width=p.name.length*7.2+20;
  svg('rect',{x:-width/2,y:5,width,height:25,rx:3},label);const text=svg('text',{x:0,y:22,'text-anchor':'middle'},label);text.textContent=p.name;
  g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleLandmark(p.id)}if(e.key==='Escape'){activeLandmark=null;drawLandmarks()}});
 }
 for(const g of layer.children){const p=landmarks.find(p=>p.id===g.dataset.landmark);g.setAttribute('transform',`translate(${point(p.lat,p.lng).join(' ')})`);g.classList.toggle('active',activeLandmark===p.id);g.setAttribute('aria-pressed',String(activeLandmark===p.id));}
}
function toggleLandmark(id){activeLandmark=activeLandmark===id?null:id;drawLandmarks();}
function mapTap(target){const dot=target.closest('[data-dot]'),landmark=target.closest('[data-landmark]');if(dot)guess(Number(dot.dataset.dot));else if(landmark)toggleLandmark(landmark.dataset.landmark);else {activeLandmark=null;drawLandmarks();}}
function drawMarkers(){if(!game||game.complete)return;$('markers').replaceChildren();$('connection').replaceChildren();const result=game.revealed?game.results.at(-1):null;
 if(result&&!result.correct){const a=point(game.photo.lat,game.photo.lng),p=photos.find(p=>p.id===result.picked),b=point(p.lat,p.lng);svg('path',{d:`M${b} L${a}`,stroke:'#ddfa45','stroke-width':2,'stroke-dasharray':'5 5',fill:'none'},$('connection'));}
 photos.forEach((p,i)=>{const [x,y]=point(p.lat,p.lng);const cls=result?(p.id===game.photo.id?' correct':p.id===result.picked?' chosen':' dim'):'';const g=svg('g',{transform:`translate(${x},${y})`,class:'dot'+cls,'data-dot':p.id,role:'button',tabindex:result||!ready?'-1':'0','aria-disabled':String(!!result||!ready),'aria-label':result?(p.id===game.photo.id?'Correct location':p.id===result.picked?'Your guess':'Other location'):`Choose location ${i+1}`},$('markers'));svg('circle',{r:23,class:'halo'},g);svg('circle',{r:10,class:'core'},g);if(result&&(p.id===game.photo.id||p.id===result.picked)){const t=svg('text',{y:0},g);t.textContent=p.id===game.photo.id?'✓':'·';}g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();guess(p.id)}});});}
function progress(){ $('round-label').textContent=`ROUND ${String(Math.min(game.index+1,5)).padStart(2,'0')} / 05`;$('progress').innerHTML=Array.from({length:5},(_,i)=>`<i class="${game.results[i]?(game.results[i].correct?'hit':'miss'):i===game.index?'current':''}"></i>`).join('');}
function startRound(){ready=false;activeLandmark=null;if(mapView)mapView.camera.fit();document.body.classList.remove('success');$('photo-status').hidden=true;$('next').disabled=true;$('next-label').textContent='PICK A DOT';$('eyebrow').textContent='FIVE PHOTOS. ONE CITY. ZERO HOMEWORK.';$('reaction').innerHTML='Which one <em>feels right?</em>';$('feedback').textContent='You don’t have to know. Just go with it.';$('photo-caption').textContent='A wall. A street. Somewhere in Vilnius.';$('map-hint').textContent='Drag to explore. Pick a lime dot.';$('map-note').textContent='FIVE DOTS. ONE PLACE.';$('frame-count').textContent=`FRAME ${String(game.index+1).padStart(3,'0')}`;$('photo-loading').hidden=false;$('photo-loading').textContent='DEVELOPING…';$('photo').style.opacity='0';$('enlarge').disabled=true;
 $('photo').onload=()=>{ready=true;$('photo-loading').hidden=true;$('photo').style.opacity='1';$('enlarge').disabled=false;drawMarkers()};$('photo').onerror=()=>{$('photo-loading').textContent='Photo could not load. Reload to try again.'};$('photo').src=game.photo.image;progress();drawMap();const upcoming=photos.filter(p=>p.id!==game.photo.id);upcoming.forEach(p=>{const im=new Image();im.src=p.image});}
function chime(correct){if(!sound)return;try{audio??=new AudioContext();audio.resume().catch(()=>{});[0,.09,.18].slice(0,correct?3:1).forEach((delay,i)=>{const o=audio.createOscillator(),v=audio.createGain();o.type='sine';o.frequency.value=correct?[440,554,740][i]:280;o.connect(v);v.connect(audio.destination);v.gain.setValueAtTime(.0001,audio.currentTime+delay);v.gain.exponentialRampToValueAtTime(.1,audio.currentTime+delay+.01);v.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+delay+.25);o.start(audio.currentTime+delay);o.stop(audio.currentTime+delay+.3)})}catch{}}
function guess(id){if(!ready||!mapReady||game.revealed||game.complete)return;const r=game.guess(id);chime(r.correct);document.body.classList.toggle('success',r.correct);$('reaction').innerHTML=r.correct?'YES. <em>That’s the spot.</em>':'A different dot. <em>Now you know.</em>';$('eyebrow').textContent=r.correct?'YOUR GUT WAS ONTO SOMETHING.':'ONE MORE PIECE OF THE CITY.';$('feedback').textContent=r.correct?'Keep that feeling. There’s another wall waiting.':`About ${r.meters>=1000?(r.meters/1000).toFixed(1)+' km':Math.round(r.meters/10)*10+' m'} away. The glowing dot is where this photo was taken.`;$('photo-status').hidden=!r.correct;$('photo-status').textContent='YES!';$('photo-caption').textContent=`${game.photo.year} · ${game.photo.title}`;$('map-note').textContent='✓ PHOTO LOCATION';$('map-hint').textContent=r.correct?'You found it.':'White: your guess. Lime: the photo.';let streak=0;for(const r of game.results.toReversed()){if(!r.correct)break;streak++}$('streak').textContent=streak>1?`${streak} IN A ROW`:'KEEP EXPLORING.';$('next').disabled=false;$('next-label').textContent=game.index===4?'SEE YOUR FIVE':'NEXT PHOTO';progress();drawMarkers();return r;}
function next(){if(!game.revealed||game.complete)return;if(game.next()){startRound();return}document.querySelector('.game-grid').hidden=true;document.querySelector('.action-bar').hidden=true;$('finish').hidden=false;const hits=game.results.filter(r=>r.correct).length;$('finish-copy').textContent=`${hits} of 5 by instinct. Five places you’ve seen a little differently.`;$('recap').replaceChildren();for(const r of game.results){const p=photos.find(p=>p.id===r.id),f=document.createElement('figure'),im=document.createElement('img'),cap=document.createElement('figcaption');im.src=p.image;im.alt=p.title;cap.innerHTML=`${r.correct?'<b>✓ Found it</b>':'A new place'}<br>${p.year}`;f.append(im,cap);$('recap').append(f)}$('replay').focus();}
$('next').onclick=next;$('replay').onclick=()=>{game=createGame(photos);$('finish').hidden=true;document.querySelector('.game-grid').hidden=false;document.querySelector('.action-bar').hidden=false;startRound()};$('sound').onclick=()=>{sound=!sound;$('sound').setAttribute('aria-pressed',String(sound));$('sound').innerHTML=`SOUND ${sound?'ON':'OFF'} <span>↗</span>`;if(sound)chime(true)};
$('enlarge').onclick=()=>{$('large-photo').src=game.photo.image;$('image-dialog').showModal()};$('credits').onclick=()=>$('credits-dialog').showModal();document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
try{const [pr,mr,lr]=await Promise.all([fetch('photos.json'),fetch('map.json'),fetch('landmarks.json')]);if(!pr.ok||!mr.ok||!lr.ok)throw Error('Content unavailable');photos=await pr.json();geometry=await mr.json();landmarks=await lr.json();mapReady=true;game=createGame(photos);$('credits-list').innerHTML=photos.map(p=>`<article><a href="${p.sourceUrl}" target="_blank" rel="noopener">${p.fileTitle}</a> · ${p.year}<br>${p.photographer} · <a href="${p.licenseUrl}" target="_blank" rel="noopener">${p.license}</a><br>Published camera geotag · approximate · resized for display.</article>`).join('');$('landmark-sources').innerHTML=landmarks.map(p=>`<a href="${p.source}" target="_blank" rel="noopener">${p.name}</a>`).join(' · ');mapView=setupMap({root:$('map'),geometry,locations:photos,landmarks,onChange:()=>{drawLandmarks();drawMarkers()},onTap:mapTap});startRound();
 const context=document.modelContext;if(context?.registerTool){for(const tool of [{name:'guess_graffiti_location',description:'Choose one anonymous map dot in the current round. Commits the guess and reveals the answer.',inputSchema:{type:'object',properties:{dot:{type:'integer',minimum:1,maximum:5}},required:['dot'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({dot})=>{if(!Number.isInteger(dot)||dot<1||dot>5)throw Error('Dot must be 1 to 5');if(!ready||game.revealed||game.complete)throw Error('Round is not accepting guesses');return guess(photos[dot-1].id)}},{name:'next_graffiti_round',description:'Advance after a revealed guess; after round five show the session recap.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(!game.revealed||game.complete)throw Error('No revealed round to advance');next();return {round:Math.min(game.index+1,5),complete:game.complete}}}]){try{Promise.resolve(context.registerTool(tool)).catch(()=>{})}catch{}}}
}catch(e){$('photo-loading').textContent='Couldn’t load the archive. Please reload.';$('map-hint').textContent='Map unavailable. Reload to try again.';console.error(e)}
